<script setup>
import {ref,onMounted} from 'vue'
import {auth,authRequest,adminFetch} from './adminApi.js'
const security=ref(null),accounts=ref([]),events=ref([]),page=ref(1),busy=ref(false),error=ref(''),notice=ref(''),password=ref(''),code=ref(''),secret=ref(null),recovery=ref([])
const newUser=ref({username:'',password:'',role:'editor'})
const labels={owner:'Владелец',admin:'Администратор',editor:'Редактор',manager:'Менеджер'}
async function get(url){const r=await adminFetch(url);if(!r.ok)throw Error((await r.json()).error||'Ошибка загрузки');return r.json()}
async function load(){security.value=await get('/api/auth/security');if(auth.user.role==='owner'){accounts.value=(await get('/api/admin/accounts')).accounts;events.value=(await get('/api/admin/audit?page='+page.value)).events}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function setup(){run(async()=>{secret.value=await authRequest('/api/auth/2fa/setup',{password:password.value});password.value='';code.value=''})}
function enable(){run(async()=>{const result=await authRequest('/api/auth/2fa/enable',{code:code.value});recovery.value=result.recovery_codes;secret.value=null;code.value='';await load()})}
function disable(){run(async()=>{await authRequest('/api/auth/2fa/disable',{password:password.value,code:code.value});password.value='';code.value='';recovery.value=[];await load();notice.value='Двухфакторный вход отключён'})}
function create(){run(async()=>{await authRequest('/api/admin/accounts',newUser.value);newUser.value={username:'',password:'',role:'editor'};await load();notice.value='Пользователь создан'})}
function save(u){run(async()=>{const r=await adminFetch('/api/admin/accounts/'+u.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({role:u.role,enabled:u.enabled})});if(!r.ok)throw Error((await r.json()).error);await load();notice.value='Права сохранены. Предыдущие сеансы пользователя завершены.'})}
function paginate(delta){run(async()=>{page.value+=delta;await load()})}
onMounted(()=>run(load))
</script>
<template>
<div class="security-workspace"><div class="page-title"><div><h1>Доступ и безопасность</h1><p>{{auth.user.username}} · {{labels[auth.user.role]}}</p></div></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<section class="panel security-panel"><h2>Двухфакторный вход</h2><p v-if="security">{{security.enabled?'Включён. При входе потребуется код из приложения-аутентификатора или резервный код.':'Защитите свою учётную запись кодом из приложения-аутентификатора.'}}</p>
<p v-if="security?.enabled">Осталось резервных кодов: {{security.recovery_remaining}}.</p>
<div v-if="recovery.length" class="recovery" role="status"><h3>Сохраните резервные коды</h3><p>Каждый код используется один раз. Они показаны только сейчас. Храните их отдельно от пароля.</p><code v-for="c in recovery" :key="c">{{c}}</code><button class="row-btn" @click="recovery=[]">Коды сохранены</button></div>
<form v-if="secret" @submit.prevent="enable"><p>В приложении-аутентификаторе добавьте ключ вручную: <strong class="secret">{{secret.secret}}</strong></p><p>Название: NOVA / {{auth.user.username}}. Код: 6 цифр, период 30 секунд.</p><a :href="secret.uri">Открыть в приложении-аутентификаторе</a><label>Код из приложения<input v-model="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></label><button class="primary-btn" :disabled="busy">Подтвердить и включить</button><button type="button" class="row-btn" @click="secret=null;code=''">Отмена</button></form>
<form v-else-if="security" @submit.prevent="security.enabled?disable():setup()"><label>Текущий пароль<input v-model="password" type="password" autocomplete="current-password" minlength="12" maxlength="256" required></label><label v-if="security.enabled">Код приложения или резервный код<input v-model="code" autocomplete="one-time-code" maxlength="30" required></label><button class="primary-btn" :disabled="busy">{{security.enabled?'Отключить двухфакторный вход':'Настроить двухфакторный вход'}}</button></form></section>
<template v-if="auth.user.role==='owner'"><section class="panel security-panel"><h2>Пользователи</h2><p>Администратор управляет сайтом и настройками. Редактор — страницами, блогом, каталогом и медиа. Менеджер — заказами, покупателями и просмотром аналитики. Пользователи, обновления и журнал доступны владельцу.</p><div class="table-wrap"><table><thead><tr><th>Логин</th><th>Роль</th><th>Доступ</th><th>2FA</th><th></th></tr></thead><tbody><tr v-for="u in accounts" :key="u.id"><td>{{u.username}}</td><td><span v-if="u.role==='owner'">Владелец</span><select v-else v-model="u.role" :disabled="busy"><option value="admin">Администратор</option><option value="editor">Редактор</option><option value="manager">Менеджер</option></select></td><td><label><input type="checkbox" v-model="u.enabled" :disabled="u.role==='owner'||busy"> Активен</label></td><td>{{u.two_factor?'Включена':'Выключена'}}</td><td><button v-if="u.role!=='owner'" class="row-btn" :disabled="busy" @click="save(u)">Сохранить</button></td></tr></tbody></table></div>
<h3>Добавить пользователя</h3><form @submit.prevent="create"><label>Логин<input v-model="newUser.username" autocomplete="off" pattern="[a-zA-Z0-9_.\-]{3,64}" minlength="3" maxlength="64" required></label><label>Первоначальный пароль<input v-model="newUser.password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></label><label>Роль<select v-model="newUser.role"><option value="admin">Администратор</option><option value="editor">Редактор</option><option value="manager">Менеджер</option></select></label><button class="primary-btn" :disabled="busy">Создать пользователя</button></form></section>
<section class="panel security-panel"><h2>Журнал действий</h2><p>Входы и изменения: кто, когда, какой раздел и результат запроса. Пароли, ключи и содержимое форм не записываются.</p><div class="table-wrap"><table><thead><tr><th>Время</th><th>Пользователь</th><th>Действие</th><th>Раздел / объект</th><th>Результат</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{new Date(e.created_at).toLocaleString('ru-RU')}}</td><td>{{e.username||'Не авторизован'}}</td><td>{{e.action}}</td><td>{{e.resource}}</td><td>{{e.status}}</td></tr><tr v-if="!events.length"><td colspan="5">Записей пока нет</td></tr></tbody></table></div><div><button class="row-btn" :disabled="busy||page===1" @click="paginate(-1)">Назад</button> Страница {{page}} <button class="row-btn" :disabled="busy||events.length<50" @click="paginate(1)">Далее</button></div></section></template>
</div>
</template>
<style scoped>
.security-panel{padding:24px;margin-bottom:24px;display:grid;gap:16px}.security-panel h2,.security-panel h3,.security-panel p{margin:0}.security-panel p{line-height:1.7;font-size:14px}.security-panel form{display:grid;gap:16px;max-width:600px}.security-panel label{display:grid;gap:8px}.security-panel input:not([type=checkbox]),.security-panel select{padding:10px;border:1px solid #cadbd0;border-radius:8px;font:inherit;min-width:0;max-width:100%}.security-panel td label{display:flex}.recovery{padding:20px;background:#eef5ef;display:grid;gap:8px;overflow-wrap:anywhere}.recovery code,.secret{user-select:all;overflow-wrap:anywhere}.security-panel td{overflow-wrap:anywhere}
</style>
